from typing import Union, Any
from weakref import WeakValueDictionary
from atexit import register

class TokenStorage:
    """Multiton class for storing and sharing access tokens per connection."""

    _instances: Any = WeakValueDictionary()

    def __new__(cls, connection_id: str):
        if connection_id not in cls._instances:
            instance = super().__new__(cls)
            cls._instances[connection_id] = instance

        return cls._instances[connection_id]

    def __init__(self, connection_id: str) -> None:
        if not hasattr(self, "_initialized"):
            self._initialized = True
            self.connection_id = connection_id

            self.access_token: Union[str, None] = None
            self.expires_at: Union[str, None] = None

    @classmethod
    def remove_instance(cls, connection_id: str) -> None:
        """Removes instance for given connection_id"""
        if connection_id in cls._instances:
            del cls._instances[connection_id]

    @classmethod
    def clear_instances(cls) -> None:
        """Removes all existing instances of TokenStorage"""
        cls._instances.clear()

register(TokenStorage.clear_instances)
